const num = (v) => {
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(String(v).replace(/\s/g, '').replace(',', '.'));
  return isNaN(n) ? 0 : n;
};
const r2 = (n) => (n === null ? null : Math.round(n * 100) / 100);
const div = (a, b) => (b ? a / b : null);

const kpis = (t) => ({
  ctr_pct: r2(div(t.clicks, t.impressions) === null ? null : div(t.clicks, t.impressions) * 100),
  cpc_pln: r2(div(t.spend, t.clicks)),
  cpa_pln: r2(div(t.spend, t.conversions)),
  roas: r2(div(t.revenue, t.spend)),
  conversion_rate_pct: r2(div(t.conversions, t.clicks) === null ? null : div(t.conversions, t.clicks) * 100),
});

const empty = () => ({ impressions: 0, clicks: 0, conversions: 0, spend: 0, revenue: 0 });
const add = (t, r) => {
  t.impressions += r.impressions; t.clicks += r.clicks; t.conversions += r.conversions;
  t.spend += r.spend; t.revenue += r.revenue;
};

const campaigns = [];
const total = empty();
const byChannel = {};

for (const item of $input.all()) {
  const j = item.json;
  if (!j.campaign) continue;
  const r = {
    impressions: num(j.impressions),
    clicks: num(j.clicks),
    conversions: num(j.conversions),
    spend: num(j.spend_pln),
    revenue: num(j.revenue_pln),
  };
  add(total, r);
  const ch = j.channel || 'Unknown';
  if (!byChannel[ch]) byChannel[ch] = empty();
  add(byChannel[ch], r);
  campaigns.push({
    campaign: j.campaign,
    channel: ch,
    campaign_type: j.campaign_type,
    date: j.date,
    impressions: r.impressions,
    clicks: r.clicks,
    conversions: r.conversions,
    spend_pln: r2(r.spend),
    revenue_pln: r2(r.revenue),
    ...kpis(r),
  });
}

const channels = Object.entries(byChannel).map(([channel, t]) => ({
  channel,
  impressions: t.impressions,
  clicks: t.clicks,
  conversions: t.conversions,
  spend_pln: r2(t.spend),
  revenue_pln: r2(t.revenue),
  ...kpis(t),
}));

return [{
  json: {
    totals: {
      impressions: total.impressions,
      clicks: total.clicks,
      conversions: total.conversions,
      spend_pln: r2(total.spend),
      revenue_pln: r2(total.revenue),
      ...kpis(total),
    },
    channels,
    campaigns,
  },
}];

